import os, sys, threading, time, json
import torch
from starVLA.rl.flow_grpo.cli import main
def memory_guard():
    while True:
        values = {}
        for path in ("/proc/meminfo", "/proc/self/status"):
            for line in open(path):
                parts = line.split()
                if parts and parts[0] in ("MemAvailable:", "VmRSS:"):
                    values[parts[0]] = int(parts[1]) * 1024
        if values.get("VmRSS:", 0) > 450 * 2**30 or values.get("MemAvailable:", 10**15) < 180 * 2**30:
            print(json.dumps({"status": "ABORT_MEMORY_GUARD", "observed": values}), file=sys.stderr, flush=True)
            os._exit(86)
        time.sleep(1)
threading.Thread(target=memory_guard, daemon=True).start()
print(json.dumps({"diagnostic_only": True, "saved_tensors": "torch.autograd.graph.save_on_cpu", "pin_memory": False, "rss_limit_gib": 450, "min_available_gib": 180}), flush=True)
with torch.autograd.graph.save_on_cpu(pin_memory=False):
    main()

